/**
 * 处理新增的摘要数据
 * 检查是否需要发布到Steemit
 */
function processNewSummary() {
  const triggerData = $json;

  // 检查触发类型是否为INSERT
  if (triggerData.type !== 'INSERT') {
    return null;
  }

  const newRecord = triggerData.record;

  // 检查是否已经发布到Steemit
  if (newRecord.steemit_posted === true) {
    return null;
  }

  // 检查必要字段是否存在
  if (!newRecord.content || !newRecord.title || !newRecord.date) {
    return null;
  }

  return {
    shouldProcess: true,
    summaryData: newRecord
  };
}

return processNewSummary();

/**
 * 为新摘要格式化Steemit发布内容
 * 添加适当的标签、格式化markdown、生成永久链接
 */
function formatSteemitContent() {
  const data = $json.summaryData;

  // 生成Steemit友好的标题
  const steemitTitle = `${data.date} AI新闻日报 | 今日科技前沿速递`;

  // 格式化内容，添加Steemit特有的元素
  const steemitContent = `
${data.content}

---

## 📊 本期统计

- 📅 **发布日期**: ${data.date}
- 📰 **精选文章**: ${data.article_count}篇
- 🤖 **AI智能筛选**: 基于多维度评估算法
- 🔗 **数据来源**: 权威科技媒体聚合

## 🏷️ 相关标签

#ai #technology #news #blockchain #steemit #中文 #科技 #人工智能 #新闻

---

> 🤖 **关于本文**
> 
> 本文由AI自动生成和发布，内容来源于公开的科技新闻报道。我们致力于为中文用户提供最新、最有价值的AI科技资讯。
> 
> 💡 **互动邀请**: 欢迎在评论区分享您对这些AI新闻的看法和见解！

---

*本文首发于 [Steemit](https://steemit.com) | 数据驱动，智能筛选*
    `;

    // 生成唯一的永久链接
    const permlink = `ai-news-${data.date.replace(/-/g, '')}-${Date.now()}`;

    return {
      summaryId: data.id,
      title: steemitTitle,
      body: steemitContent,
      tags: ['ai', 'technology', 'news', 'blockchain', 'steemit', '中文', '科技', '人工智能', '新闻'],
      category: 'technology',
      permlink: permlink,
      originalDate: data.date,
      originalTitle: data.title
    };
}

return formatSteemitContent();

/**
 * 准备Steemit API调用参数
 * 生成发布操作的完整参数
 */
function prepareSteemitApiCall() {
  const postData = $json;

  // Steemit发布操作参数
  const commentOp = [
    'comment',
    {
      parent_author: '',
      parent_permlink: postData.category,
      author: '{{ $credentials.steemitAccount.username }}',
      permlink: postData.permlink,
      title: postData.title,
      body: postData.body,
      json_metadata: JSON.stringify({
        tags: postData.tags,
        app: 'n8n-auto-poster/1.0',
        format: 'markdown',
        canonical_url: `https://steemit.com/@{{ $credentials.steemitAccount.username }}/${postData.permlink}`,
        description: `${postData.originalDate} AI新闻综述 - 精选${postData.tags.length}个热门话题`
      })
    }
  ];

  return {
    operation: commentOp,
    postData: postData,
    timestamp: new Date().toISOString()
  };
}

return prepareSteemitApiCall();

/**
 * 处理Steemit API响应并准备数据库更新
 * 检查发布状态并生成相应的更新数据
 */
function processSteemitResponse() {
  const apiResponse = $json;
  const postData = $('Prepare Steemit API Call').first().json.postData;

  let updateData = {
    id: postData.summaryId,
    steemit_posted_at: new Date().toISOString()
  };

  if (apiResponse.result && apiResponse.result.id) {
    // 发布成功
    updateData.steemit_posted = true;
    updateData.steemit_url = `https://steemit.com/@{{ $credentials.steemitAccount.username }}/${postData.permlink}`;
    updateData.steemit_transaction_id = apiResponse.result.id;
    updateData.steemit_block_num = apiResponse.result.block_num;
    updateData.steemit_status = 'published';
  } else {
    // 发布失败
    updateData.steemit_posted = false;
    updateData.steemit_error = JSON.stringify(apiResponse.error || 'Unknown error');
    updateData.steemit_status = 'failed';
    updateData.retry_count = (postData.retry_count || 0) + 1;
  }

  return updateData;
}

return processSteemitResponse();

/**
 * 生成同步操作的详细日志
 * 记录成功和失败的详细信息
 */
function generateSyncLog() {
  const updateResult = $json;
  const originalPost = $('Format Steemit Content').first().json;

  const logEntry = {
    timestamp: new Date().toISOString(),
    operation: 'steemit_sync_realtime',
    summary_id: updateResult.id || originalPost.summaryId,
    status: updateResult.steemit_posted ? 'success' : 'failed',
    steemit_url: updateResult.steemit_url,
    transaction_id: updateResult.steemit_transaction_id,
    block_num: updateResult.steemit_block_num,
    error: updateResult.steemit_error,
    retry_count: updateResult.retry_count || 0,
    post_title: originalPost.title,
    post_date: originalPost.originalDate,
    trigger_type: 'database_insert'
  };

  return logEntry;
}

return generateSyncLog();
